import re,json,hashlib,collections,pathlib
root=pathlib.Path.cwd()
out=root/'docs/validation/farm_enclosed_valley_20260909'
def snapshot(path):
 raw=path.read_bytes(); txt=raw.decode('utf-8-sig')
 blocks={}
 for m in re.finditer(r'^--- !u!(\d+) &(\d+)\r?\n(.*?)(?=^--- !u!|\Z)',txt,re.M|re.S):
  blocks[m[2]]={'type':int(m[1]),'body':m[3]}
 def field(body,name):
  m=re.search(r'^  '+re.escape(name)+r':(.*)$',body,re.M)
  return m[1].strip() if m else ''
 def fid(value):
  m=re.search(r'fileID: (\d+)',value); return m[1] if m else '0'
 transforms={fid(field(b['body'],'m_GameObject')):key for key,b in blocks.items() if b['type'] in (4,224)}
 cache={}
 def pathof(go):
  if go in cache:return cache[go]
  if go not in blocks:return '<missing:'+go+'>'
  name=field(blocks[go]['body'],'m_Name')
  tr=blocks.get(transforms.get(go),{})
  parent=fid(field(tr.get('body',''),'m_Father'))
  parentgo=fid(field(blocks.get(parent,{}).get('body',''),'m_GameObject'))
  result=(pathof(parentgo)+'/' if parent!='0' else '')+name
  cache[go]=result;return result
 def label(key):
  b=blocks.get(key)
  if not b:return 'null' if key=='0' else '<missing:'+key+'>'
  go=key if b['type']==1 else fid(field(b['body'],'m_GameObject'))
  kind=field(b['body'],'m_EditorClassIdentifier') or b['body'].split(':',1)[0]
  return pathof(go)+'#'+kind if go!='0' else kind
 def norm(body):
  return re.sub(r'\{fileID: (\d+)\}',lambda m:'{ref: '+label(m[1])+'}',body)
 records={}; ids={}; moves={}; regs={}
 for key,b in blocks.items():
  body=b['body']; kind=b['type']; name=label(key)
  if kind==114:
   records[name]=norm(body)
   selected={}
   for m in re.finditer(r'^  (_\w*(?:Id|ID|Index)|_npcData|_treeData): (.*)$',body,re.M):
    selected[m[1]]=norm(m[2])
   if selected:ids[name]=selected
   for fieldname in ('_trees','_treeNodes','_farmPlots','_plots'):
    m=re.search(r'^  '+fieldname+r':\s*\n((?:  - .*\n)*)',body,re.M)
    if m:regs[name+'/'+fieldname]=sorted(label(x) for x in re.findall(r'fileID: (\d+)',m[1]))
  if kind==4:moves[name]={f:field(body,f) for f in ('m_LocalPosition','m_LocalScale','m_LocalRotation')}
 counts=collections.Counter(b['body'].split(':',1)[0] for b in blocks.values())
 exterior=collections.Counter(b['body'].split(':',1)[0] for k,b in blocks.items() if 'FarmPerimeterVisuals' in label(k))
 return {'sha256':hashlib.sha256(raw).hexdigest(),'counts':dict(counts),'exterior_counts':dict(exterior),'ids':ids,'registries':regs,'monobehaviours':records,'transforms':moves}
before=snapshot(out/'FarmScene.before.unity.backup')
after=snapshot(root/'Assets/_Game/Scenes/FarmScene.unity')
def compare(a,b):
 return {k:{'before':a.get(k),'after':b.get(k)} for k in sorted(a.keys()|b.keys()) if a.get(k)!=b.get(k)}
result={'before_sha256':before['sha256'],'after_sha256':after['sha256'],'counts_before':before['counts'],'counts_after':after['counts'],'exterior_after':after['exterior_counts'],'id_differences':compare(before['ids'],after['ids']),'registry_differences':compare(before['registries'],after['registries']),'registry_counts_before':{k:len(v) for k,v in before['registries'].items()},'registry_counts_after':{k:len(v) for k,v in after['registries'].items()},'monobehaviour_differences':compare(before['monobehaviours'],after['monobehaviours']),'existing_transform_changes':{k:{'before':v,'after':after['transforms'][k]} for k,v in before['transforms'].items() if k in after['transforms'] and v!=after['transforms'][k]},'limitations':'Text parser for saved Unity YAML; local references normalized by hierarchy/type, list order retained except registries explicitly sorted. Duplicate same-type components on one object can collide in map. External asset contents not compared. Does not prove runtime/visual behavior.'}
(out/'identity-inventory-comparison.json').write_text(json.dumps(result,indent=2,ensure_ascii=False),encoding='utf-8')
print(json.dumps({k:v for k,v in result.items() if k not in ('monobehaviour_differences','existing_transform_changes')},indent=2))
print('changed_MB',len(result['monobehaviour_differences']),'moved_existing_transforms',len(result['existing_transform_changes']))
